-- The Cozy Science Lab: existing-project upgrade. Keeps accounts, quiz records, teacher edits and stock.
begin;
-- Platform upgrade, assembled with the canonical bank by backend:sql.
-- Apply upgrade.sql as the project owner. No browser credential can run DDL.
alter table public.csl_profiles add column if not exists active boolean not null default true;
alter table public.csl_profiles add column if not exists photo_path text;

create table if not exists public.csl_settings (
 id boolean primary key default true check(id), rules jsonb not null, game jsonb not null, version bigint not null default 1
);
insert into public.csl_settings(id,rules,game) values(true,'{"starterMerits":24,"comboBonus":1,"timezone":"Asia/Manila","meritEasy":3,"meritMedium":5,"meritHard":7,"dailyCap":120,"correctXP":12,"attemptXP":3,"xpPerLevel":120,"comboEvery":3,"reviewReward":2,"dailyReward":10,"questReward":8,"spinMax":12,"skillsLevel":4}'::jsonb,'{"seconds":[20,16,12],"motion":[5,3.5,2],"points":100,"penalty":25,"coins":3,"timeCost":3,"dartCost":2}'::jsonb) on conflict(id) do nothing;
create table if not exists public.csl_wallets (
 user_id uuid primary key references public.csl_profiles(user_id) on delete cascade,
 credits integer not null default 0 check(credits between 0 and 10000000)
);
create table if not exists public.csl_credit_ledger (
 id uuid primary key default gen_random_uuid(), user_id uuid not null references public.csl_profiles(user_id) on delete cascade,
 kind text not null, reference text not null, amount integer not null, note text not null default '', created_at timestamptz not null default now(),
 unique(user_id,kind,reference)
);
create index if not exists csl_credit_ledger_user_time on public.csl_credit_ledger(user_id,created_at);
create table if not exists public.csl_items (
 id text primary key check(id ~ '^[a-z0-9_-]{1,64}$'), name text not null check(char_length(name) between 2 and 80),
 description text not null default '' check(char_length(description)<=500), price integer not null check(price between 1 and 10000),
 stock integer not null check(stock between 0 and 100000), icon text not null, color text not null, category text not null,
 active boolean not null default true, version bigint not null default 1
);
insert into public.csl_items(id,name,description,price,stock,icon,color,category) select v->>'id',v->>'name',v->>'description',(v->>'price')::int,(v->>'stock')::int,v->>'icon',v->>'color',v->>'category' from jsonb_array_elements('[{"id":"pencil","name":"Little idea pencils","description":"Two trusty pencils for your next bright idea.","price":35,"stock":24,"icon":"pencils","color":"yellow","category":"School essentials"},{"id":"notebook","name":"Discovery notebook","description":"A fresh little home for your science wonders.","price":65,"stock":15,"icon":"notebook","color":"green","category":"School essentials"},{"id":"ruler","name":"Measure of wonder","description":"A 30 cm ruler. Big discoveries need good measures.","price":45,"stock":20,"icon":"ruler","color":"blue","category":"Lab companions"},{"id":"markers","name":"Colorful connections","description":"A set of highlighters for ideas that stand out.","price":90,"stock":10,"icon":"markers","color":"peach","category":"School essentials"},{"id":"goggles","name":"Curiosity goggles","description":"A pair of safety goggles for supervised lab work.","price":150,"stock":8,"icon":"goggles","color":"lilac","category":"Lab companions"},{"id":"sticky","name":"Tiny thought notes","description":"Sticky notes to keep your a-ha moments close.","price":30,"stock":30,"icon":"sticky","color":"yellow","category":"School essentials"}]'::jsonb) v on conflict(id) do nothing;
create table if not exists public.csl_orders (
 id uuid primary key default gen_random_uuid(), user_id uuid not null references public.csl_profiles(user_id) on delete cascade,
 request_id uuid not null, item_id text not null references public.csl_items(id), item_name text not null, price integer not null check(price>0),
 code text not null unique, status text not null default 'reserved' check(status in ('reserved','collected','cancelled')),
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,request_id)
);
create index if not exists csl_orders_user_time on public.csl_orders(user_id,created_at desc);
create table if not exists public.csl_question_overrides (
 question_id text primary key, question jsonb not null, active boolean not null default true, version bigint not null default 1,
 updated_at timestamptz not null default now()
);
create table if not exists csl_private.question_versions (
 question_id text not null references csl_private.questions(id), revision integer not null check(revision>=0), question jsonb not null,
 primary key(question_id,revision)
);
alter table csl_private.question_versions enable row level security;
revoke all on csl_private.question_versions from public,anon,authenticated;
create or replace function csl_private.normalized_answers(value jsonb) returns jsonb language sql immutable set search_path='' as $$
 select coalesce(jsonb_agg(a||jsonb_build_object('question_version',coalesce(a->'question_version','0'::jsonb))),'[]') from jsonb_array_elements(value) a;
$$;
revoke all on function csl_private.normalized_answers(jsonb) from public,anon,authenticated;
create table if not exists public.csl_attempt_notes (
 attempt_id uuid primary key references public.csl_quiz_attempts(id) on delete cascade,
 note text not null check(char_length(note)<=500), teacher_id uuid references auth.users(id) on delete set null, updated_at timestamptz not null default now()
);
create table if not exists public.csl_teacher_activity (
 id bigint generated always as identity primary key, actor uuid references auth.users(id) on delete set null,
 action text not null, subject text not null, note text not null default '', before_value jsonb, after_value jsonb,
 created_at timestamptz not null default now()
);
create table if not exists csl_private.teacher_requests (
 actor uuid not null references auth.users(id) on delete cascade, request_id uuid not null, action text not null, body jsonb not null, result jsonb not null,
 primary key(actor,request_id)
);
do $$ declare t text; begin
 foreach t in array array['csl_settings','csl_wallets','csl_credit_ledger','csl_items','csl_orders','csl_question_overrides','csl_attempt_notes','csl_teacher_activity'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
 end loop;
end $$;
alter table csl_private.teacher_requests enable row level security;
revoke all on csl_private.teacher_requests from public,anon,authenticated;

create or replace function public.csl_has_access() returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.csl_profiles where user_id=(select auth.uid()) and active);
$$;
revoke all on function public.csl_has_access() from public,anon;
grant execute on function public.csl_has_access() to authenticated;
create or replace function public.csl_is_teacher() returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.csl_teachers t join public.csl_profiles p using(user_id) where t.user_id=(select auth.uid()) and p.active);
$$;
create or replace function csl_private.actor(expected uuid default null) returns uuid language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid(); begin
 if uid is null or (expected is not null and expected is distinct from uid) then raise exception 'Sign in with the account that started this action.' using errcode='42501'; end if;
 if not public.csl_has_access() then raise exception 'Your account is paused. Please contact your teacher.' using errcode='42501'; end if;
 return uid;
end $$;
create or replace function csl_private.teacher() returns uuid language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=csl_private.actor(); begin
 if not public.csl_is_teacher() then raise exception 'Teacher access is required.' using errcode='42501'; end if; return uid;
end $$;
drop policy if exists csl_profiles_read on public.csl_profiles;
create policy csl_profiles_read on public.csl_profiles for select to authenticated using(public.csl_has_access() and (user_id=auth.uid() or public.csl_is_teacher()));
drop policy if exists csl_attempts_read on public.csl_quiz_attempts;
create policy csl_attempts_read on public.csl_quiz_attempts for select to authenticated using(public.csl_has_access() and (user_id=auth.uid() or public.csl_is_teacher()));

create or replace function csl_private.create_wallet() returns trigger language plpgsql security definer set search_path='' as $$
begin
 insert into public.csl_wallets(user_id,credits) values(new.user_id,coalesce((select (rules->>'starterMerits')::int from public.csl_settings where id),24)) on conflict do nothing;
 return new;
end $$;
drop trigger if exists csl_profile_wallet on public.csl_profiles;
create trigger csl_profile_wallet after insert on public.csl_profiles for each row execute function csl_private.create_wallet();
insert into public.csl_wallets(user_id,credits) select user_id,(select (rules->>'starterMerits')::int from public.csl_settings where id) from public.csl_profiles on conflict do nothing;

create or replace function csl_private.credit_award(uid uuid,kind_value text,ref text,requested integer) returns integer language plpgsql security definer set search_path='' as $$
declare cfg jsonb; used integer; award integer; day_value date; begin
 if requested<0 or requested>10000 then raise exception 'Invalid credit award.'; end if;
 perform 1 from public.csl_wallets where user_id=uid for update;
 if exists(select 1 from public.csl_credit_ledger where user_id=uid and kind=kind_value and reference=ref) then return 0; end if;
 select rules into cfg from public.csl_settings where id;
 day_value:=(clock_timestamp() at time zone (cfg->>'timezone'))::date;
 select coalesce(sum(amount),0) into used from public.csl_credit_ledger where user_id=uid and kind in ('quiz','arcade') and (created_at at time zone (cfg->>'timezone'))::date=day_value;
 award:=greatest(0,least(requested,(cfg->>'dailyCap')::int-used));
 insert into public.csl_credit_ledger(user_id,kind,reference,amount) values(uid,kind_value,ref,award);
 update public.csl_wallets set credits=credits+award where user_id=uid;
 return award;
end $$;
create or replace function csl_private.credit_attempt(attempt uuid) returns void language plpgsql security definer set search_path='' as $$
declare a public.csl_quiz_attempts; cfg jsonb; earned integer:=0; streak integer:=0; entry jsonb; rate integer; begin
 select * into a from public.csl_quiz_attempts where id=attempt;
 if not found then raise exception 'Quiz record not found.'; end if;
 select rules into cfg from public.csl_settings where id;
 rate:=(cfg->>case a.level when 'easy' then 'meritEasy' when 'medium' then 'meritMedium' else 'meritHard' end)::int;
 for entry in select value from jsonb_array_elements(a.responses) loop
  if (entry->>'correct')::boolean then
   streak:=streak+1; earned:=earned+rate+case when streak%(cfg->>'comboEvery')::int=0 then (cfg->>'comboBonus')::int else 0 end;
  else streak:=0; end if;
 end loop;
 perform csl_private.credit_award(a.user_id,'quiz',a.id::text,earned);
end $$;

create or replace function public.csl_backend_status() returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('version',1,'questions',(select count(*) from csl_private.questions),'platform',2);
$$;
create or replace function public.csl_my_profile() returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=csl_private.actor(); p public.csl_profiles; begin
 select * into p from public.csl_profiles where user_id=uid;
 return jsonb_build_object('user_id',p.user_id,'display_name',p.display_name,'grade',p.grade,'section',p.section,'is_teacher',public.csl_is_teacher(),'photo_path',p.photo_path,'credits',(select credits from public.csl_wallets where user_id=uid));
end $$;
create or replace function public.csl_update_profile(p_name text,p_grade integer,p_section text,p_user_id uuid) returns void language plpgsql security definer set search_path='' as $$
declare uid uuid:=csl_private.actor(p_user_id); begin
 if char_length(btrim(p_name)) not between 2 and 40 or p_grade not between 7 and 10 or char_length(p_section)>40 or p_name is null or p_grade is null or p_section is null then raise exception 'Check your name, grade and section.'; end if;
 update public.csl_profiles set display_name=btrim(p_name),grade=p_grade,section=btrim(p_section) where user_id=uid;
end $$;
create or replace function public.csl_my_lab(p_user_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=csl_private.actor(p_user_id); cfg public.csl_settings; begin
 select * into cfg from public.csl_settings where id;
 return jsonb_build_object('credits',(select credits from public.csl_wallets where user_id=uid),'rules',cfg.rules,'game',cfg.game,'settings_version',cfg.version,
  'items',coalesce((select jsonb_agg(to_jsonb(i) order by i.category,i.name) from public.csl_items i where active),'[]'),
  'orders',coalesce((select jsonb_agg(to_jsonb(o) order by o.created_at desc) from (select * from public.csl_orders where user_id=uid order by created_at desc limit 200) o),'[]'),
  'overrides',coalesce((select jsonb_agg(jsonb_build_object('question',question,'active',active,'version',version)) from public.csl_question_overrides),'[]'));
end $$;
revoke all on function public.csl_my_lab(uuid) from public,anon;
grant execute on function public.csl_my_lab(uuid) to authenticated;

create or replace function public.csl_reserve_item(p_user_id uuid,p_request_id uuid,p_item_id text,p_expected_price integer,p_expected_version bigint) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=csl_private.actor(p_user_id); item public.csl_items; previous public.csl_orders; result public.csl_orders; balance integer; begin
 if p_request_id is null then raise exception 'A reservation ID is required.'; end if;
 select credits into balance from public.csl_wallets where user_id=uid for update;
 select * into previous from public.csl_orders where user_id=uid and request_id=p_request_id;
 if found then
  if previous.item_id is distinct from p_item_id or previous.price is distinct from p_expected_price then raise exception 'This reservation ID belongs to another request.'; end if;
  return to_jsonb(previous);
 end if;
 select * into item from public.csl_items where id=p_item_id for update;
 if not found or not item.active or item.stock<1 then raise exception 'This item is out of stock. Refresh the shelf.'; end if;
 if item.price is distinct from p_expected_price or item.version is distinct from p_expected_version then raise exception 'This item changed. Refresh the shelf and review its price before reserving.'; end if;
 if balance<item.price then raise exception 'You need more class credits for this item.'; end if;
 update public.csl_wallets set credits=credits-item.price where user_id=uid;
 update public.csl_items set stock=stock-1,version=version+1 where id=item.id;
 insert into public.csl_orders(user_id,request_id,item_id,item_name,price,code) values(uid,p_request_id,item.id,item.name,item.price,'CSL-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))) returning * into result;
 insert into public.csl_credit_ledger(user_id,kind,reference,amount,note) values(uid,'reservation',result.id::text,-item.price,item.name);
 return to_jsonb(result);
end $$;
revoke all on function public.csl_reserve_item(uuid,uuid,text,integer,bigint) from public,anon;
grant execute on function public.csl_reserve_item(uuid,uuid,text,integer,bigint) to authenticated;

-- Images are private; signed read URLs are created only for authorized viewers.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
 values('csl-avatars','csl-avatars',false,262144,array['image/webp'])
 on conflict(id) do update set public=false,file_size_limit=262144,allowed_mime_types=array['image/webp'];
drop policy if exists csl_avatar_read on storage.objects;
create policy csl_avatar_read on storage.objects for select to authenticated using(bucket_id='csl-avatars' and public.csl_has_access() and (split_part(name,'/',1)=auth.uid()::text or public.csl_is_teacher()));
drop policy if exists csl_avatar_insert on storage.objects;
create policy csl_avatar_insert on storage.objects for insert to authenticated with check(bucket_id='csl-avatars' and public.csl_has_access() and split_part(name,'/',1)=auth.uid()::text and name ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.webp$');
drop policy if exists csl_avatar_delete on storage.objects;
create policy csl_avatar_delete on storage.objects for delete to authenticated using(bucket_id='csl-avatars' and public.csl_has_access() and split_part(name,'/',1)=auth.uid()::text);
create or replace function public.csl_set_photo(p_user_id uuid,p_path text) returns void language plpgsql security definer set search_path='' as $$
declare uid uuid:=csl_private.actor(p_user_id); begin
 if p_path is not null and (split_part(p_path,'/',1)<>uid::text or p_path !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.webp$' or not exists(select 1 from storage.objects where bucket_id='csl-avatars' and name=p_path)) then raise exception 'Upload a valid profile photo to your own folder.'; end if;
 update public.csl_profiles set photo_path=p_path where user_id=uid;
end $$;
revoke all on function public.csl_set_photo(uuid,text) from public,anon;
grant execute on function public.csl_set_photo(uuid,text) to authenticated;

revoke all on function csl_private.actor(uuid),csl_private.teacher(),csl_private.create_wallet(),csl_private.credit_award(uuid,text,text,integer),csl_private.credit_attempt(uuid) from public,anon,authenticated;

create table if not exists public.csl_arcade_sessions (
 id uuid primary key, user_id uuid not null references public.csl_profiles(user_id) on delete cascade,
 category text not null check(category in ('life','chemistry','physics','earth')), state jsonb not null, questions jsonb not null,
 created_at timestamptz not null default now(), completed_at timestamptz
);
create index if not exists csl_arcade_sessions_user_time on public.csl_arcade_sessions(user_id,created_at desc);
create table if not exists csl_private.arcade_commands (
 session_id uuid not null references public.csl_arcade_sessions(id) on delete cascade, command_id uuid not null, body jsonb not null,
 primary key(session_id,command_id)
);
alter table public.csl_arcade_sessions enable row level security;
alter table csl_private.arcade_commands enable row level security;
revoke all on public.csl_arcade_sessions,csl_private.arcade_commands from public,anon,authenticated;

create or replace function csl_private.now_ms() returns bigint language sql volatile set search_path='' as $$ select floor(extract(epoch from clock_timestamp())*1000)::bigint; $$;
create or replace function csl_private.arcade_view(game_id uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare g public.csl_arcade_sessions; q jsonb; begin
 select * into g from public.csl_arcade_sessions where id=game_id;
 if not found then raise exception 'This arcade round could not be found.'; end if;
 q:=case when (g.state->>'completed')::boolean then null else g.questions->(g.state->>'index')::int end;
 return jsonb_build_object('state',g.state,'question',q-'answer'-'accept'-'tolerance'-'explanation'-'scienceFact','serverNow',csl_private.now_ms());
end $$;
create or replace function public.csl_arcade_start(p_user_id uuid,p_category text,p_request_id uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare uid uuid:=csl_private.actor(p_user_id); previous public.csl_arcade_sessions; cards jsonb:='[]'; chunk jsonb; ids jsonb; cfg jsonb; t bigint; lev text; begin
 if p_category is null or p_category not in ('life','chemistry','physics','earth') or p_request_id is null then raise exception 'Choose a science arcade category.'; end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text||'arcade',5));
 select * into previous from public.csl_arcade_sessions where id=p_request_id;
 if found then
  if previous.user_id<>uid or previous.category<>p_category then raise exception 'This round ID was already used.'; end if; return csl_private.arcade_view(previous.id);
 end if;
 foreach lev in array array['easy','medium','hard'] loop
  select coalesce(jsonb_agg(question),'[]') into chunk from (
   select b.question from csl_private.questions b left join public.csl_question_overrides o on o.question_id=b.id
   where split_part(b.question->>'deckId','.',1)=p_category and b.question->>'level'=lev and b.question->>'type'='mcq' and jsonb_array_length(b.question->'options')=4 and coalesce(o.active,true)
   order by random() limit 3
  ) bank;
  if jsonb_array_length(chunk)<>3 then raise exception 'This category needs three reviewed four-choice cards at every level.'; end if;
  cards:=cards||chunk;
 end loop;
 select jsonb_agg(value->>'id') into ids from jsonb_array_elements(cards);
 select game into cfg from public.csl_settings where id; t:=csl_private.now_ms();
 update public.csl_arcade_sessions set completed_at=now() where user_id=uid and completed_at is null;
 insert into public.csl_arcade_sessions(id,user_id,category,questions,state)
 values(p_request_id,uid,p_category,cards,jsonb_build_object('version',1,'revision',0,'id',p_request_id,'userId',uid,'category',p_category,'ids',ids,'index',0,'score',0,'coins',0,'combo',0,'correct',0,'darts',2,'wrong','[]'::jsonb,'timeUsed',false,'dartUsed',false,'deadline',t+(cfg->'seconds'->>0)::int*1000,'reloadUntil',t,'created',t,'completed',false,'rules',cfg));
 return csl_private.arcade_view(p_request_id);
end $$;
revoke all on function public.csl_arcade_start(uuid,text,uuid) from public,anon;
grant execute on function public.csl_arcade_start(uuid,text,uuid) to authenticated;

create or replace function public.csl_arcade_current(p_user_id uuid) returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare uid uuid:=csl_private.actor(p_user_id); game_id uuid; begin
 select id into game_id from public.csl_arcade_sessions where user_id=uid and completed_at is null order by created_at desc limit 1;
 if game_id is null then return null; end if; return csl_private.arcade_view(game_id);
end $$;
revoke all on function public.csl_arcade_current(uuid) from public,anon;
grant execute on function public.csl_arcade_current(uuid) to authenticated;

create or replace function public.csl_arcade_action(p_user_id uuid,p_session_id uuid,p_command_id uuid,p_question_id text,p_action text,p_option text default '') returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare uid uuid:=csl_private.actor(p_user_id); g public.csl_arcade_sessions; s jsonb; q jsonb; cfg jsonb; old_body jsonb; body jsonb; feedback jsonb;
 t bigint; idx integer; score_value integer; coins_value integer; combo_value integer; correct_value integer; darts_value integer; wrong_value jsonb; multiplier integer:=1;
 deadline_value bigint; reload_value bigint; time_used boolean; dart_used boolean; advance boolean:=false; complete boolean:=false; answer_text text; explanation text;
begin
 if p_command_id is null or p_action is null or p_action not in ('shoot','timeout','time','dart') or char_length(coalesce(p_option,''))>80 then raise exception 'This arcade action is not valid.'; end if;
 select * into g from public.csl_arcade_sessions where id=p_session_id for update;
 if not found or g.user_id<>uid then raise exception 'This round belongs to another account.' using errcode='42501'; end if;
 body:=jsonb_build_object('question',p_question_id,'action',p_action,'option',coalesce(p_option,''));
 select b.body into old_body from csl_private.arcade_commands b where session_id=g.id and command_id=p_command_id;
 if found then
  if old_body<>body then raise exception 'This shot ID was already used.'; end if; return csl_private.arcade_view(g.id);
 end if;
 s:=g.state;
 if (s->>'completed')::boolean or g.completed_at is not null then raise exception 'This arcade round is finished.'; end if;
 idx:=(s->>'index')::int; q:=g.questions->idx;
 if q->>'id' is distinct from p_question_id then raise exception 'This discovery already moved on. Refresh the round.'; end if;
 cfg:=s->'rules'; t:=csl_private.now_ms(); deadline_value:=(s->>'deadline')::bigint; reload_value:=(s->>'reloadUntil')::bigint;
 score_value:=(s->>'score')::int; coins_value:=(s->>'coins')::int; combo_value:=(s->>'combo')::int; correct_value:=(s->>'correct')::int; darts_value:=(s->>'darts')::int;
 wrong_value:=s->'wrong'; time_used:=(s->>'timeUsed')::boolean; dart_used:=(s->>'dartUsed')::boolean; feedback:=s->'feedback';
 select value->>'text' into answer_text from jsonb_array_elements(q->'options') where value->>'id'=q->>'answer';
 explanation:=coalesce(q->>'explanation','A new science discovery is ready.');
 if t>=deadline_value then
  score_value:=greatest(0,score_value-(cfg->>'penalty')::int); coins_value:=greatest(0,coins_value-1); combo_value:=0; advance:=true;
  feedback:=jsonb_build_object('kind','timeout','text','Time’s up. Let’s discover why.','answer',answer_text,'explanation',explanation,'multiplier',1);
 elsif p_action='timeout' then return csl_private.arcade_view(g.id);
 elsif p_action='time' then
  if time_used or coins_value<(cfg->>'timeCost')::int then raise exception 'Extra time needs more round coins, or was already used on this card.'; end if;
  coins_value:=coins_value-(cfg->>'timeCost')::int; time_used:=true; deadline_value:=deadline_value+5000;
 elsif p_action='dart' then
  if dart_used or coins_value<(cfg->>'dartCost')::int then raise exception 'An extra dart needs more round coins, or was already used on this card.'; end if;
  coins_value:=coins_value-(cfg->>'dartCost')::int; dart_used:=true; darts_value:=darts_value+1;
 else
  if t<reload_value then raise exception 'Reloading. Your next dart is ready in one second.'; end if;
  if wrong_value?coalesce(p_option,'') then raise exception 'Try another target.'; end if;
  if coalesce(p_option,'')<>'__miss__' and not exists(select 1 from jsonb_array_elements(q->'options') where value->>'id'=p_option) then raise exception 'Aim at one of the targets to shoot.'; end if;
  darts_value:=darts_value-1; reload_value:=t+1000;
  if p_option=q->>'answer' then
   combo_value:=combo_value+1; correct_value:=correct_value+1; multiplier:=least(3,1+combo_value/3);
   score_value:=score_value+(cfg->>'points')::int*multiplier; coins_value:=coins_value+(cfg->>'coins')::int; advance:=true;
   feedback:=jsonb_build_object('kind','correct','text',case when multiplier>1 then 'Bullseye! ×'||multiplier||' combo.' else 'Bullseye! A bright discovery.' end,'answer',answer_text,'explanation',explanation,'multiplier',multiplier);
  else
   combo_value:=0; score_value:=greatest(0,score_value-(cfg->>'penalty')::int); coins_value:=greatest(0,coins_value-1);
   if p_option<>'__miss__' then wrong_value:=wrong_value||jsonb_build_array(p_option); end if;
   feedback:=jsonb_build_object('kind',case when p_option='__miss__' then 'miss' else 'wrong' end,'text',case when darts_value>0 then 'A mix-up. Reload and try another target.' else 'Out of darts. A new discovery is next.' end,'multiplier',1);
   if darts_value=0 then advance:=true; feedback:=feedback||jsonb_build_object('answer',answer_text,'explanation',explanation); end if;
  end if;
 end if;
 if advance then
  idx:=idx+1; complete:=idx>=9; darts_value:=2; wrong_value:='[]'; time_used:=false; dart_used:=false; reload_value:=t+1000;
  deadline_value:=case when complete then t else t+1000+(cfg->'seconds'->>least(2,idx/3))::int*1000 end;
 end if;
 s:=s||jsonb_build_object('revision',(s->>'revision')::int+1,'index',idx,'score',score_value,'coins',coins_value,'combo',combo_value,'correct',correct_value,'darts',darts_value,'wrong',wrong_value,'timeUsed',time_used,'dartUsed',dart_used,'deadline',deadline_value,'reloadUntil',reload_value,'completed',complete,'feedback',feedback);
 update public.csl_arcade_sessions set state=s,completed_at=case when complete then now() else null end where id=g.id;
 insert into csl_private.arcade_commands(session_id,command_id,body) values(g.id,p_command_id,body);
 if complete then perform csl_private.credit_award(uid,'arcade',g.id::text,correct_value); end if;
 return csl_private.arcade_view(g.id);
end $$;
revoke all on function public.csl_arcade_action(uuid,uuid,uuid,text,text,text) from public,anon;
grant execute on function public.csl_arcade_action(uuid,uuid,uuid,text,text,text) to authenticated;

create or replace function public.csl_arcade_rankings(p_category text default 'all') returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=csl_private.actor(); result jsonb; begin
 if p_category is null or p_category not in ('all','life','chemistry','physics','earth') then raise exception 'Choose a leaderboard category.'; end if;
 with best as (
  select distinct on(g.user_id) g.user_id,p.display_name,g.category,(g.state->>'score')::int score,(g.state->>'correct')::int correct,g.completed_at
  from public.csl_arcade_sessions g join public.csl_profiles p using(user_id)
  where p.active and g.state->>'completed'='true' and (p_category='all' or g.category=p_category)
  order by g.user_id,(g.state->>'score')::int desc,(g.state->>'correct')::int desc,g.completed_at,g.id
 ), ranked as (select row_number() over(order by score desc,correct desc,completed_at,user_id) rank,* from best)
 select coalesce(jsonb_agg(to_jsonb(r)),'[]') into result from (select * from ranked order by rank limit 100) r;
 return result;
end $$;
revoke all on function public.csl_arcade_rankings(text) from public,anon;
grant execute on function public.csl_arcade_rankings(text) to authenticated;
revoke all on function csl_private.now_ms(),csl_private.arcade_view(uuid) from public,anon,authenticated;

create or replace function csl_private.integer_field(v jsonb,k text,lo integer,hi integer) returns integer language plpgsql immutable set search_path='' as $$
declare n integer; begin
 if (jsonb_typeof(v->k)='number' and (v->>k) ~ '^-?[0-9]+$') is not true then raise exception 'Use a whole number for %.',k; end if;
 n:=(v->>k)::integer; if n<lo or n>hi then raise exception '% must be between % and %.',k,lo,hi; end if; return n;
exception when numeric_value_out_of_range then raise exception 'That number is too large.';
end $$;
create or replace function csl_private.valid_game(g jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare v jsonb; previous numeric:=100; n numeric; begin
 if jsonb_typeof(g)<>'object' or jsonb_array_length(g->'seconds')<>3 or jsonb_array_length(g->'motion')<>3 then return false; end if;
 for v in select value from jsonb_array_elements(g->'seconds') loop
  if jsonb_typeof(v)<>'number' or v::text !~ '^[0-9]+$' then return false; end if;
  n:=v::text::numeric; if n<8 or n>60 or n>previous then return false; end if; previous:=n;
 end loop;
 previous:=100;
 for v in select value from jsonb_array_elements(g->'motion') loop
  if jsonb_typeof(v)<>'number' then return false; end if;
  n:=v::text::numeric; if n<1.25 or n>8 or n>previous then return false; end if; previous:=n;
 end loop;
 perform csl_private.integer_field(g,'points',1,500),csl_private.integer_field(g,'penalty',1,500),csl_private.integer_field(g,'coins',1,10),csl_private.integer_field(g,'timeCost',1,20),csl_private.integer_field(g,'dartCost',1,20);
 return (g->>'penalty')::int<=(g->>'points')::int;
exception when others then return false;
end $$;
create or replace function csl_private.valid_rules(r jsonb) returns boolean language plpgsql stable set search_path='' as $$
declare k text; begin
 if jsonb_typeof(r)<>'object' or not exists(select 1 from pg_catalog.pg_timezone_names where name=r->>'timezone') then return false; end if;
 if r?'pickupLocation' and (jsonb_typeof(r->'pickupLocation') is distinct from 'string' or char_length(btrim(r->>'pickupLocation')) not between 2 and 160) then return false; end if;
 foreach k in array array['starterMerits','comboBonus','meritEasy','meritMedium','meritHard','dailyCap','correctXP','attemptXP','xpPerLevel','comboEvery','reviewReward','dailyReward','questReward','spinMax','skillsLevel'] loop
  perform csl_private.integer_field(r,k,case when k in ('xpPerLevel','comboEvery','skillsLevel') then 1 else 0 end,case when k='xpPerLevel' then 10000 when k='dailyCap' then 1000 when k='starterMerits' then 200 when k='skillsLevel' then 100 else 500 end);
 end loop;
 return true;
exception when others then return false;
end $$;

create or replace function public.csl_teacher_command(p_request_id uuid,p_action text,p_body jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=csl_private.teacher(); previous csl_private.teacher_requests; result jsonb:='{"ok":true}'; before_value jsonb; after_value jsonb;
 target text; note_value text:=''; target_user uuid; n integer; balance integer; item public.csl_items; ord public.csl_orders; cfg public.csl_settings;
 q jsonb; old_q jsonb; entry jsonb; ids text[]:='{}'; version_value bigint; active_value boolean;
begin
 if p_request_id is null or jsonb_typeof(p_body) is distinct from 'object' or octet_length(p_body::text)>100000 then raise exception 'This change could not be validated.'; end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text||p_request_id::text,2));
 select * into previous from csl_private.teacher_requests where actor=uid and request_id=p_request_id;
 if found then
  if previous.action is distinct from p_action or previous.body is distinct from p_body then raise exception 'This change ID was already used.'; end if;
  return previous.result;
 end if;
 if p_action='student' then
  if p_body?'reason' then note_value:=btrim(p_body->>'reason'); if note_value is null or char_length(note_value) not between 3 and 300 then raise exception 'Add a reason of 3-300 characters.'; end if; end if;
  target_user:=(p_body->>'user_id')::uuid; target:=target_user::text;
  select to_jsonb(p) into before_value from public.csl_profiles p where user_id=target_user for update;
  if before_value is null then raise exception 'Student not found.'; end if;
  if char_length(btrim(p_body->>'display_name')) not between 2 and 40 or char_length(p_body->>'section')>40 or jsonb_typeof(p_body->'active') is distinct from 'boolean' or p_body->>'display_name' is null or p_body->>'section' is null then raise exception 'Check the student name, section and account status.'; end if;
  n:=csl_private.integer_field(p_body,'grade',7,10);
  if (p_body->>'active')::boolean=false and exists(select 1 from public.csl_teachers where user_id=target_user) then raise exception 'Teacher access is managed by the site owner.'; end if;
  if p_body->>'expected_updated' is distinct from md5(before_value::text) then raise exception 'This student profile changed. Refresh before saving.'; end if;
  update public.csl_profiles set display_name=btrim(p_body->>'display_name'),grade=n,section=btrim(p_body->>'section'),active=(p_body->>'active')::boolean where user_id=target_user returning to_jsonb(csl_profiles.*) into after_value;
 elsif p_action='credits' then
  target_user:=(p_body->>'user_id')::uuid; target:=target_user::text;
  n:=csl_private.integer_field(p_body,'delta',-10000,10000); note_value:=btrim(p_body->>'reason');
  if char_length(note_value) not between 3 and 300 or note_value is null then raise exception 'Add a reason of 3–300 characters.'; end if;
  select credits into balance from public.csl_wallets where user_id=target_user for update;
  if not found or balance+n<0 then raise exception 'Check the student and balance. Credits cannot go below zero.'; end if;
  before_value:=jsonb_build_object('credits',balance);
  update public.csl_wallets set credits=credits+n where user_id=target_user;
  insert into public.csl_credit_ledger(user_id,kind,reference,amount,note) values(target_user,'teacher',p_request_id::text,n,note_value);
  after_value:=jsonb_build_object('credits',balance+n);
 elsif p_action='item' then
  target:=p_body->>'id';
  if target is null or target !~ '^[a-z0-9_-]{1,64}$' or char_length(btrim(p_body->>'name')) not between 2 and 80 or char_length(p_body->>'description')>500 or char_length(btrim(p_body->>'category')) not between 2 and 40 or p_body->>'name' is null or p_body->>'description' is null or p_body->>'category' is null then raise exception 'Check the supply name, description and category.'; end if;
  if (p_body->>'icon' in ('pencils','notebook','ruler','markers','goggles','sticky') and p_body->>'color' in ('yellow','green','blue','peach','lilac') and jsonb_typeof(p_body->'active')='boolean') is not true then raise exception 'Choose a valid supply illustration, color and visibility.'; end if;
  perform pg_advisory_xact_lock(hashtextextended(target,3));
  select * into item from public.csl_items where id=target for update;
  version_value:=case when found then item.version else 0 end;
  if csl_private.integer_field(p_body,'version',0,2147483647)<>version_value then raise exception 'This supply changed. Refresh before saving.'; end if;
  before_value:=case when version_value=0 then null else to_jsonb(item) end;
  insert into public.csl_items(id,name,description,price,stock,icon,color,category,active,version)
   values(target,btrim(p_body->>'name'),p_body->>'description',csl_private.integer_field(p_body,'price',1,10000),csl_private.integer_field(p_body,'stock',0,100000),p_body->>'icon',p_body->>'color',btrim(p_body->>'category'),(p_body->>'active')::boolean,version_value+1)
   on conflict(id) do update set name=excluded.name,description=excluded.description,price=excluded.price,stock=excluded.stock,icon=excluded.icon,color=excluded.color,category=excluded.category,active=excluded.active,version=excluded.version
   returning to_jsonb(csl_items.*) into after_value;
 elsif p_action='claim' then
  target:=p_body->>'id';
  select * into ord from public.csl_orders where id=target::uuid for update;
  if not found or ord.status<>'reserved' then raise exception 'This reservation has already been handled. Refresh the claims.'; end if;
  before_value:=to_jsonb(ord); note_value:=left(coalesce(p_body->>'reason',''),300);
  if p_body->>'status'='collected' then
   if upper(btrim(p_body->>'code')) is distinct from ord.code then raise exception 'Check the claim code shown by the student.'; end if;
   update public.csl_orders set status='collected',updated_at=now() where id=ord.id returning to_jsonb(csl_orders.*) into after_value;
  elsif p_body->>'status'='cancelled' then
   if char_length(btrim(note_value))<3 then raise exception 'Add a cancellation reason.'; end if;
   perform 1 from public.csl_wallets where user_id=ord.user_id for update;
   update public.csl_wallets set credits=credits+ord.price where user_id=ord.user_id;
   update public.csl_items set stock=stock+1,version=version+1 where id=ord.item_id;
   insert into public.csl_credit_ledger(user_id,kind,reference,amount,note) values(ord.user_id,'refund',ord.id::text,ord.price,note_value);
   update public.csl_orders set status='cancelled',updated_at=now() where id=ord.id returning to_jsonb(csl_orders.*) into after_value;
  else raise exception 'Choose collection or cancellation.'; end if;
 elsif p_action in ('rules','game') then
  target:='settings'; select * into cfg from public.csl_settings where id for update;
  if csl_private.integer_field(p_body,'version',1,2147483647)<>cfg.version then raise exception 'These settings changed. Refresh before saving.'; end if;
  before_value:=to_jsonb(cfg);
  if p_action='rules' then
   if not csl_private.valid_rules(p_body->'rules') then raise exception 'Check the learning rules, limits and timezone.'; end if;
   update public.csl_settings set rules=p_body->'rules',version=version+1 where id returning to_jsonb(csl_settings.*) into after_value;
  else
   if not csl_private.valid_game(p_body->'game') then raise exception 'Use three decreasing time and movement levels, with valid score and coin settings.'; end if;
   update public.csl_settings set game=p_body->'game',version=version+1 where id returning to_jsonb(csl_settings.*) into after_value;
  end if;
 elsif p_action='question' then
  q:=p_body->'question'; target:=q->>'id';
  perform pg_advisory_xact_lock(hashtextextended(coalesce(target,''),4));
  select question into old_q from csl_private.questions where id=target;
  if not found then raise exception 'Choose an existing published card.'; end if;
  if (q->>'deckId'=old_q->>'deckId' and q->>'level'=old_q->>'level' and q->>'type'=old_q->>'type' and q->>'topic'=q->>'deckId' and char_length(btrim(q->>'prompt')) between 10 and 500 and char_length(q->>'explanation') between 20 and 220 and char_length(btrim(q->>'scienceFact')) between 2 and 500 and q->'reviewed'='true'::jsonb and jsonb_typeof(p_body->'active')='boolean') is not true then raise exception 'Keep the card identity and type. Add a reviewed prompt, explanation and science fact.'; end if;
  perform csl_private.integer_field(q,'gradeBand',7,10);
  if jsonb_typeof(q->'answer') is distinct from jsonb_typeof(old_q->'answer') then raise exception 'Keep the answer format for this card type.'; end if;
  if q->'options' is not null then
   if jsonb_typeof(q->'options')<>'array' or jsonb_array_length(q->'options')<>jsonb_array_length(old_q->'options') then raise exception 'Keep the expected number of choices.'; end if;
   for entry in select value from jsonb_array_elements(q->'options') loop
    if (char_length(entry->>'id') between 1 and 80 and char_length(btrim(entry->>'text')) between 1 and 300 and not (entry->>'id'=any(ids))) is not true then raise exception 'Use different choice IDs and nonempty choice text.'; end if; ids:=array_append(ids,entry->>'id');
   end loop;
   if q->>'type' in ('mcq','truefalse','diagram','data') and not (q->>'answer'=any(ids)) then raise exception 'Choose exactly one listed correct answer.'; end if;
  end if;
  select coalesce(max(version),0) into version_value from public.csl_question_overrides where question_id=target;
  if csl_private.integer_field(p_body,'version',0,2147483647)<>version_value then raise exception 'This card changed. Refresh before saving.'; end if;
  active_value:=(p_body->>'active')::boolean;
  if not active_value and (select count(*) from csl_private.questions b left join public.csl_question_overrides o on o.question_id=b.id where b.question->>'deckId'=q->>'deckId' and b.question->>'level'=q->>'level' and b.id<>target and coalesce(o.active,true))<8 then raise exception 'Keep at least eight active cards at each deck level.'; end if;
  if not active_value and q->>'type'='mcq' and (select count(*) from csl_private.questions b left join public.csl_question_overrides o on o.question_id=b.id where split_part(b.question->>'deckId','.',1)=split_part(q->>'deckId','.',1) and b.question->>'level'=q->>'level' and b.question->>'type'='mcq' and b.id<>target and coalesce(o.active,true))<3 then raise exception 'Keep three arcade cards at each category level.'; end if;
  before_value:=jsonb_build_object('question',old_q,'active',coalesce((select active from public.csl_question_overrides where question_id=target),true),'version',version_value);
  insert into csl_private.question_versions(question_id,revision,question) values(target,version_value,old_q) on conflict do nothing;
  insert into csl_private.question_versions(question_id,revision,question) values(target,version_value+1,q);
  insert into public.csl_question_overrides(question_id,question,active,version) values(target,q,active_value,version_value+1) on conflict(question_id) do update set question=q,active=active_value,version=version_value+1,updated_at=now();
  update csl_private.questions set question=q where id=target;
  after_value:=jsonb_build_object('question',q,'active',active_value,'version',version_value+1);
 elsif p_action='feedback' then
  target:=p_body->>'attempt_id'; note_value:=btrim(p_body->>'note');
  if note_value is null or char_length(note_value)>500 or not exists(select 1 from public.csl_quiz_attempts where id=target::uuid) then raise exception 'Choose a quiz record and a note of up to 500 characters.'; end if;
  select to_jsonb(n) into before_value from public.csl_attempt_notes n where attempt_id=target::uuid;
  insert into public.csl_attempt_notes(attempt_id,note,teacher_id) values(target::uuid,note_value,uid) on conflict(attempt_id) do update set note=excluded.note,teacher_id=uid,updated_at=now() returning to_jsonb(csl_attempt_notes.*) into after_value;
 else raise exception 'This teacher action is not available.'; end if;
 insert into public.csl_teacher_activity(actor,action,subject,note,before_value,after_value) values(uid,p_action,target,note_value,before_value,after_value);
 result:=jsonb_build_object('ok',true,'value',after_value);
 insert into csl_private.teacher_requests(actor,request_id,action,body,result) values(uid,p_request_id,p_action,p_body,result);
 return result;
end $$;
revoke all on function public.csl_teacher_command(uuid,text,jsonb) from public,anon;
grant execute on function public.csl_teacher_command(uuid,text,jsonb) to authenticated;

create or replace function public.csl_teacher_data(p_view text,p_filters jsonb default '{}',p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=csl_private.teacher(); result jsonb; query_value text:=left(coalesce(p_filters->>'search',''),100); grade_value integer:=nullif(p_filters->>'grade','')::int; section_value text:=left(coalesce(p_filters->>'section',''),40); off_value integer:=greatest(0,least(coalesce(p_offset,0),1000000)); begin
 if p_view='overview' then
  result:=jsonb_build_object('stats',jsonb_build_object(
   'students',(select count(*) from public.csl_profiles p where not exists(select 1 from public.csl_teachers t where t.user_id=p.user_id)),
   'active',(select count(*) from public.csl_profiles p where active and not exists(select 1 from public.csl_teachers t where t.user_id=p.user_id)),
   'attempts',(select count(*) from public.csl_quiz_attempts),
   'correct',(select coalesce(sum(correct),0) from public.csl_quiz_attempts),
   'answers',(select coalesce(sum(total),0) from public.csl_quiz_attempts),
   'pending',(select count(*) from public.csl_orders where status='reserved'),
   'low_stock',(select count(*) from public.csl_items where active and stock<=5),
   'games',(select count(*) from public.csl_arcade_sessions where state->>'completed'='true')),
   'charts',coalesce((select jsonb_agg(to_jsonb(c)) from (select deck_id,count(*) attempts,sum(correct) correct,sum(total) total from public.csl_quiz_attempts group by deck_id order by count(*) desc,deck_id limit 12) c),'[]'),
   'rows','[]'::jsonb,'total',0);
 elsif p_view='students' then
  with filtered as (
   select p.*,w.credits,exists(select 1 from public.csl_teachers t where t.user_id=p.user_id) is_teacher,
    md5(to_jsonb(p)::text) expected_updated,(select count(*) from public.csl_quiz_attempts a where a.user_id=p.user_id) attempts
   from public.csl_profiles p join public.csl_wallets w using(user_id)
   where (query_value='' or p.display_name ilike '%'||query_value||'%') and (grade_value is null or p.grade=grade_value) and (section_value='' or p.section ilike '%'||section_value||'%')
  ) select jsonb_build_object('total',count(*),'rows',coalesce((select jsonb_agg(to_jsonb(r)) from (select * from filtered order by display_name,user_id limit 50 offset off_value) r),'[]')) into result from filtered;
 elsif p_view='shop' then
  with filtered as (select * from public.csl_items where query_value='' or name ilike '%'||query_value||'%')
  select jsonb_build_object('total',count(*),'rows',coalesce((select jsonb_agg(to_jsonb(r)) from (select * from filtered order by active desc,name,id limit 50 offset off_value) r),'[]')) into result from filtered;
 elsif p_view='claims' then
  with filtered as (
   select o.*,p.display_name,p.grade,p.section from public.csl_orders o join public.csl_profiles p using(user_id)
   where (query_value='' or p.display_name ilike '%'||query_value||'%' or o.code ilike '%'||query_value||'%') and (grade_value is null or p.grade=grade_value) and (section_value='' or p.section ilike '%'||section_value||'%') and (coalesce(p_filters->>'status','')='' or o.status=p_filters->>'status')
  ) select jsonb_build_object('total',count(*),'rows',coalesce((select jsonb_agg(to_jsonb(r)) from (select * from filtered order by created_at desc,id desc limit 50 offset off_value) r),'[]')) into result from filtered;
 elsif p_view='reports' then
  with filtered as (
   select a.id,a.user_id,p.display_name,p.grade,p.section,a.deck_id,a.level,a.mode,a.correct,a.total,a.received_at,a.responses,coalesce(n.note,'') teacher_note
   from public.csl_quiz_attempts a join public.csl_profiles p using(user_id) left join public.csl_attempt_notes n on n.attempt_id=a.id
   where (query_value='' or p.display_name ilike '%'||query_value||'%') and (grade_value is null or p.grade=grade_value) and (section_value='' or p.section ilike '%'||section_value||'%') and (coalesce(p_filters->>'deck','')='' or a.deck_id=p_filters->>'deck')
  ) select jsonb_build_object('total',count(*),'stats',jsonb_build_object('attempts',count(*),'correct',coalesce(sum(correct),0),'answers',coalesce(sum(total),0)),'rows',coalesce((select jsonb_agg(to_jsonb(r)) from (select * from filtered order by received_at desc,id desc limit 50 offset off_value) r),'[]')) into result from filtered;
 elsif p_view='content' then
  with filtered as (
   select b.question,coalesce(o.active,true) active,coalesce(o.version,0) version from csl_private.questions b left join public.csl_question_overrides o on o.question_id=b.id
   where (query_value='' or b.question->>'prompt' ilike '%'||query_value||'%') and (coalesce(p_filters->>'deck','')='' or b.question->>'deckId'=p_filters->>'deck')
  ) select jsonb_build_object('total',count(*),'rows',coalesce((select jsonb_agg(to_jsonb(r)) from (select * from filtered order by question->>'deckId',question->>'level',question->>'id' limit 50 offset off_value) r),'[]')) into result from filtered;
 elsif p_view='settings' then
  select jsonb_build_object('rows',jsonb_build_array(to_jsonb(s)),'total',1) into result from public.csl_settings s where id;
 elsif p_view='activity' then
  with filtered as (
   select a.*,p.display_name actor_name from public.csl_teacher_activity a left join public.csl_profiles p on p.user_id=a.actor where query_value='' or a.action ilike '%'||query_value||'%' or a.note ilike '%'||query_value||'%'
  ) select jsonb_build_object('total',count(*),'rows',coalesce((select jsonb_agg(to_jsonb(r)) from (select * from filtered order by created_at desc,id desc limit 50 offset off_value) r),'[]')) into result from filtered;
 else raise exception 'Choose a teacher workspace section.'; end if;
 return result;
end $$;
revoke all on function public.csl_teacher_data(text,jsonb,integer) from public,anon;
grant execute on function public.csl_teacher_data(text,jsonb,integer) to authenticated;
revoke all on function csl_private.integer_field(jsonb,text,integer,integer),csl_private.valid_game(jsonb),csl_private.valid_rules(jsonb) from public,anon,authenticated;

create or replace function public.csl_record_quiz(p_client_run_id uuid,p_deck_id text,p_level text,p_mode text,p_started_at timestamptz,p_answers jsonb,p_user_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare uid uuid:=csl_private.actor(p_user_id); previous public.csl_quiz_attempts; entry jsonb; q jsonb; graded jsonb:='[]'; seen text[]:='{}'; ok boolean; correct_count integer:=0; total_count integer; created_id uuid; chosen jsonb;
begin
  if uid is null or p_user_id is distinct from uid then raise exception 'Sign in with the account that completed this quiz.' using errcode='42501'; end if;
  if not exists(select 1 from public.csl_profiles where user_id=uid) then raise exception 'Your cloud profile is not ready.'; end if;
  if p_client_run_id is null or p_deck_id is null or char_length(p_deck_id)>100 or p_level is null or p_level not in ('easy','medium','hard') or p_mode is null or p_mode not in ('practice','review','daily','boss') or p_started_at is null or p_started_at>'2100-01-01'::timestamptz or p_started_at<'2020-01-01'::timestamptz or p_answers is null or jsonb_typeof(p_answers)<>'array' or octet_length(p_answers::text)>100000 then raise exception 'This quiz record is not valid.'; end if;
  total_count:=jsonb_array_length(p_answers);
  if total_count not between 1 and 8 then raise exception 'Save between one and eight answered cards.'; end if;
  -- Serialize concurrent retries for this authenticated user's attempt.
  perform pg_advisory_xact_lock(hashtextextended(uid::text||p_client_run_id::text,0));
  select * into previous from public.csl_quiz_attempts where user_id=uid and client_run_id=p_client_run_id;
  if found then
    if previous.deck_id<>p_deck_id or previous.level<>p_level or previous.mode<>p_mode or csl_private.normalized_answers(previous.submitted_answers)<>csl_private.normalized_answers(p_answers) then raise exception 'This attempt ID already belongs to a different submission.'; end if;
    return jsonb_build_object('id',previous.id,'correct',previous.correct,'total',previous.total);
  end if;
  for entry in select value from jsonb_array_elements(p_answers) loop
    if jsonb_typeof(entry)<>'object' or jsonb_typeof(entry->'question_id')<>'string' or not (entry?'value') or jsonb_typeof(entry->'value') not in ('string','array','object') or (entry->>'question_id')=any(seen) then raise exception 'This quiz contains an invalid or repeated card.'; end if;
    seen:=array_append(seen,entry->>'question_id');
    if entry?'question_version' and (jsonb_typeof(entry->'question_version')='number' and entry->>'question_version' ~ '^[0-9]{1,10}$') is not true then raise exception 'This question version is not valid.'; end if;
    select question into q from csl_private.question_versions where question_id=entry->>'question_id' and revision=coalesce((entry->>'question_version')::integer,0);
    if not found or q->>'deckId'<>p_deck_id or (p_mode<>'review' and q->>'level'<>p_level) then raise exception 'This quiz card does not match the published question bank.'; end if;
    ok:=csl_private.correct_answer(q,entry->'value');
    if ok then correct_count:=correct_count+1; end if;
    chosen:=null;
    if not ok then select value into chosen from jsonb_array_elements(coalesce(q->'options','[]')) where value->>'id'=entry->>'value'; end if;
    graded:=graded||jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('question_id',entry->>'question_id','value',entry->'value','correct',ok,'prompt',q->>'prompt','misconception',chosen->>'misconception')));
  end loop;
  insert into public.csl_quiz_attempts(user_id,client_run_id,deck_id,level,mode,started_at,submitted_answers,responses,correct,total)
    values(uid,p_client_run_id,p_deck_id,p_level,p_mode,p_started_at,p_answers,graded,correct_count,total_count) returning id into created_id;
  perform csl_private.credit_attempt(created_id);
  return jsonb_build_object('id',created_id,'correct',correct_count,'total',total_count);
end $$;
